WITH transactions_by_account AS (SELECT account_id, ROUND((100 * SUM(CASE WHEN merchant = 'Amazon' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_amazon, COUNT(DISTINCT amount) AS unique_merchants FROM transactions GROUP BY account_id) SELECT a.balance, tba.pct_amazon, tba.unique_merchants FROM accounts a INNER JOIN transactions_by_account tba ON a.id = tba.account_id WHERE tba.pct_amazon >= 59 ORDER BY pct_amazon DESC;
